window.POETRY_REGISTER("v5-extra-9-10-0-d1403a328cb5.js",{"poems":[[15384,2],[26514,2],[26516,2],[28100,2],[49184,2],[49185,2],[52094,2],[52209,2],[52291,2],[52301,2],[52310,2],[52956,2],[53418,2],[54475,2],[55813,2],[57946,2],[59008,7],[72842,7],[87372,7],[104989,7],[105299,7],[105300,7],[109547,7],[121718,7],[129866,7],[140225,7],[191169,7],[192130,7],[219026,7],[219405,7],[220927,7],[221364,7],[224366,7],[233440,7],[233445,7],[236005,7],[238528,7],[250736,7],[267739,7],[271499,7],[271951,7],[272022,7],[273922,7],[281840,7],[283043,7],[285742,7],[285743,7],[285959,7],[287950,7],[287952,7],[288883,7],[290730,7],[295325,7],[296332,7],[297731,7],[299341,7],[299350,7],[301576,7],[301601,7],[304563,7],[317146,7],[318174,7],[321250,7],[340212,9],[346528,9],[346975,9],[351009,9],[356745,9],[359688,9],[359693,9],[361351,9],[368191,10],[368387,10],[369790,10],[373001,10],[373003,10],[375300,10],[375306,10],[375309,10],[380143,10],[381853,0],[381867,0],[382247,0],[395317,13],[411225,8],[416975,8],[420369,8],[425745,8],[433140,8],[436482,8],[437038,8],[442436,8],[442494,8],[444004,8],[451828,8],[453355,8],[453908,8],[453910,8],[471170,8],[479475,8],[484278,8],[486353,8],[488526,8],[488527,8],[488531,8],[488534,8],[488542,8],[506011,8],[519319,8],[524005,8],[540595,8],[554184,8],[556446,8],[566064,8],[593340,8],[608066,8],[621261,8],[630355,8],[636933,15],[646993,15],[648431,16],[648443,16],[648482,16],[648488,16],[648687,16],[649510,5],[650074,5],[650385,5],[651559,5],[653290,5],[658676,5],[658981,5],[662070,5],[670944,5],[671605,5],[680916,5],[701886,5],[703920,5],[707633,5],[709993,5],[711881,5],[735220,5],[739680,20],[739685,20]],"pairs":[["不因礼部张公将尔来","如何得声名一旦諠九垓",0],["却后二十六年能几时","汝不思二十五六年来事",1],["亦欲与尔表里相辉光","尔不见当今甲第与王宫",2],["处端卓兮赴下而忘鄙","集人之祈兮从人之所市",3],["五帝垂衣兮修之不忒","以心体之者为四海之主",4],["潇湘隔别兮水阔烟深","谁能绝圣韬贤餐芝饵术",5],["作者的思想并不高超","只是哭愁哭病思念家乡",6],["二句得了却作究竟还","三句作不信但看槽上驴",7],["乃知此本为芋仙旧藏","芋仙与莼斋有缟纻之雅",8],["钱塘县尉瑯琊王纾书","天宝五载夏五月二十日",9],["今日何日兮共此良辰","与君觥浊酒而藉落英兮",10],["并云此院唐时名碧流","吴越时因避讳更名碧沼",11],["后客死于攸县司空山","又引高阆语称为国初人",12],["又玄静先生即李含光","为茅山宗第十三代宗师",13],["岳珂云此诗真迹一卷","嘉定甲申九月赎之邵邸",14],["然十首非皆赵志之作","第十首即署为司户萨照",15],["便唤作无由再逢伊面","近日来不期而会重欢宴",16],["只恐不禁愁绝易飘零","待得南楼三弄彻君试看",17],["秋水横按兮半提可灭","使八极顶目者不自争衡",18],["劝君邪佞党中休入手","岂不知潞州处士田佐时",19],["陶先生归来但寻松菊","若论檀栾之操无敌于君",20],["磊落群居在牛丞相宅","昔时大士常命汝曰听徒",21],["象笾玉豆兮金鼎煇煌","海珍野蔌兮杂错而致诚",22],["雷公睥睨不可以挥斧","老鹤飞来势欲止而复还",23],["不以世俗琐屑累寥廓","愚观翁之子孙诜诜绳绳",24],["回抱山麓兮入于苍渊","流来孔多兮自溢于林间",25],["千山万山叠叠高门户","又不见光孝僧堂六七间",26],["花鸟水竹兮聊尔平泉","公有豫章楩楠兮耸万仞",27],["飘然南山之南北山北","君不见岳飞功成不抽身",28],["解道峨眉山月半轮秋","又不见苏家老仙冰啄句",29],["有贤父兄子弟未渠贤","君不见祖孙父子兄与弟",30],["袭万壑之清冰而在躬","耿吾独传中郎之素业兮",31],["中有一气亘天如白虹","又不见徂徕之山十丈雪",32],["骨专车兮以徇于天下","于越守东藩而奉其祀兮",33],["荆榛塞路兮下穿我履","望苍梧兮将重华之云愬",34],["能不抱孙兮乐亲以戏","子如不暇恤兮亲宁忍忘",35],["可敬而慕兮几春复秋","意其存兮閟千万年之原",36],["有时蛤蜊遽食龟壳秋","彼升元阁者亟成而复坏",37],["中有青鸾黄鹤千万对","雄倡雌和迭舞而交鸣兮",38],["正恐钟卫二王无合作","君不见此老一去知几年",39],["世固待之以褚颜之节","而岂复侪之于芝繇之伦",40],["凡六人者皆有所抗论","独雍首尾噤然若不预者",41],["此林氏子以是语语我","我亦以是语信其医之良",42],["诸大老何用许多气力","山僧寻常只是因风吹火",43],["曷为乎鸿荒之不再世","吾将揭北斗而量九州兮",44],["了绝喜怒哀乐爱恶欲","练空碧毓紫冲兮身如玉",45],["观徼妙兮常有欲无欲","吾将先天后天明月之珠",46],["廪石高贮兮可以忘饥","红尘迥绝兮山中发兰桂",47],["究厥后凋兮基于不竞","使与春争妍兮曷保常真",48],["一唱三叹兮亦孔之惙","盍置诸左右兮观省昭揭",49],["无非蘧蘧栩栩梦庄周","空教笑倒江上烟雨汀鸥",50],["又无大药可以玄双蓬","何怪乎玉雪可怜之孺子",51],["默已不堪兮哭微更苦","儿孙为吾一恸兮万万古",52],["或云水气专一不解散","胡不为长河玉岸之寒冰",53],["或云阴气胁阳不相入","胡不为氤氲五色之卿霭",53],["相彼胎禽兮有志凌霄","翦翎铩翼兮羁縻于笼牢",54],["夏居其难秋若居其易","君不见当年秦焰焦中州",55],["衍之又衍至于千百亿","寿翁以金书玉箓长生符",56],["外可以舒畅诗书之香","上可以奉萱庭寿康之庆",57],["絮袄不具有识空悲伤","又不见范叔一寒如此极",58],["我王库内岂有是刀哉","古今多少人以橘皮为火",59],["念我平生兮思君鬰陶","在师中兮岂造次之可离",60],["既绝望乎鸠杖与糜粥","曾不见富人之哀我茕独",61],["世间闲是闲非皆如此","君不见李白携月到夜郎",62],["生事不及思之极天兮","思兮思兮岂徒劳吾神兮",63],["碧桃花下无日不春风","我欲访山阴旧隐与参同",64],["能对大官说尔之肺腹","应令猺子感眼眦迸垂浆",65],["撼屋松风三日吹不醒","安知便以神为马尻为轮",66],["不如孝女英烈能捐生","又不见湘妃江边泪斑竹",67],["沂之两厓兮有枣树桑","居沂之人兮宽裕而善良",68],["远而不见兮涉江与淮","岂无人兮余望余之所思",69],["忆昔天风吹我登其堂","饮我以金茎八月之沆瀣",70],["以廉售欲岂比长安清","亦何必隐居辛苦注草经",71],["牵牛何来兮饮吾上流","彼以天下让兮我以之逃",72],["奈此人间小黠并大痴","君不见陶潜弃官归故里",73],["回视彼抗尘走俗之辈","蜂房课蜜之功甚时可办",74],["信知古人嗜好不在酒","爱其果能助发英锐之志",75],["弹鸾养枭兮莫知其咎","斲冰以承宫兮曷云能又",76],["我闻在昔兮有虞夏商","一夫百亩兮家有稻与梁",77],["彼湖有波兮此栯有柳","我维我舟兮聊以搔我首",78],["有箨住罾兮有沙在罶","逝者滔滔兮羌不可以久",78],["龙虎名区兮列仙之伦","剪云制衣兮结云以为神",79],["道祐有德兮吴卒自屠","雪我王宿耻兮威振八都",80],["军伍难更兮势如貔䝙","行行各努力兮于乎于乎",80],["寡妇念此兮泣下数行","呜呼哀哉兮死者不可忘",81],["登彼西山兮采其薇矣","以暴易暴兮不知其非矣",82],["世间闲是闲非皆如此","君不见李白携月到夜郎",83],["安得龙舟数千夫八万","君不见江都城外人图侬",84],["不饮莫待两鬓成衰蓬","君不见东风晓作梨花梦",85],["悔不日日独酌三千卮","又不见王敦不饮恺杀婢",86],["但见人间此乐乐陶陶","自不知蟠桃之熟应几遭",87],["太令小令声名绝今古","何天经地纬而山峙川融",88],["莫饮瓦瓮所酿之松花","我不愿范雎折齿作秦相",89],["君不见米南宫天下名","父子貌得潇湘晴云暗雨",90],["怅独处此兮情莫能娱","怀佳人兮路修阻而莫随",91],["风无宁日兮木无宁柯","念儿有身兮乃父母之枝",92],["君子有常小人中非兮","外缜内贞羌有此淑行兮",93],["母疾之殆兮儿生何为","身死母可代兮儿甘如饴",94],["坐见凄凄白露满芳草","愿采青松寄情亲于远道",95],["报汝以离离朱瑟之绳","绳以发凌云绝响之妙曲",96],["但见古城苍苍生绿莱","上则盘冈曲丘龙蛇虎蹲",97],["谢家荣庭兰玉敢争妍","安得共此君一邱一壑里",98],["何必怀金纡紫谒帝庐","又何必求仙问道访茅屋",99],["惟思种椿搆堂怡其亲","君不见椿枝长茂椿叶重",100],["望见山西境上多白骨","我愿君王耳聪听几万里",101],["爰有卫霍兮固我圉疆","胡皇舆枉御兮六飞劝勷",102],["猗嗟豸冠兮生者为殇","归气作厉兮犹剿乎犬羊",102],["断云没鹘兮彼天一方","精英烨煌兮逐雁以南翔",102],["亲昵何在兮环视维他","连蹇孱弱兮惟赢童之是",103],["身世华蟫兮朝绎暮䌷","焕烂秾郁兮内绷而外彪",104],["云杉露草兮山阿水涯","我怀我痛兮云何其不悲",105],["人弗尔若兮徒涕而泗","匪天降酷兮实我罪之遗",106],["贤甥地官祝在图与诗","君不见萱花丛开傍慈竹",107],["虎豹吟风兮猿猱啸雨","君胡为兮远嚣环而结宇",108],["赤管岁月却与吾曹俦","君不见南海欧生亦闭关",109],["徒然白璧售毁青蝇缁","又不记华阴县里骑驴日",110],["丹梯百级悬藤挂树边","一上一回气欲绝而辄止",111],["若玉荣之坚栗而葳蕤","又不则化尔为员丘之竹",112],["上有巉岩磊砢之奇石","覆以千年之松百年之柏",113],["惊人骇兽相视莫先语","我亦欲乘桴凌此万里渚",114],["君亦胡为局促如辕驹","君乎何不为神龙之变化",115],["坐见凄凄白露满芳草","愿采青松寄情亲于远道",116],["风无宁日兮木无宁柯","念儿有身兮乃父母之枝",117],["行当驻颜却老明方瞳","君不见九子山加九华号",118],["则无往而不在者斯泉","安必其下在渊而上在天",119],["梦中执手兮一喜一悲","觉后痛吾心兮无休歇时",120],["苦我怨气兮浩于长空","六合虽广兮受之应不容",120],["巧佞在前兮贤者灭息","尧舜圣已没兮孰为忠直",121],["高山崔巍兮水流汤汤","死日将至兮与麋鹿如坈",121],["自快中野兮苍天与直","于嗟不可悔兮宁早自贼",122],["宫殿中可以避世全身","何必深山之中蒿庐之下",123],["巧佞在前兮贤者灭息","尧舜圣已没兮孰为忠直",124],["高山崔巍兮水流汤汤","死日将至兮与麋鹿如坈",124],["呜呼将才孰谓今无人","君不见二陈一葛三将军",125],["顶灯的裴瑾挨些嘴巴","活吃人的盗跖得了好死",126],["榆林遭殃才滚就了椽","庖牺氏人首蛇身古而怪",126],["一更里荷包照样儿穿","这周朝的王业根茎里旺",126],["河崖上两场瞎关了兵","到其间武王纵有千张嘴",126],["谁是谁非也说不分明","都说是无道昏君合该死",126],["陕西的秦家得了风水","他那蚕食方法起的心高",126],["只这开手一着便不佳","玄武门谋杀建成和元吉",126],["日光摩荡又属了赵家","陈桥兵变道的是禅了位",126],["金銮殿上把孝棒儿拖","血沥沥十族拐上了朋友",126],["到头来谁见把秋挨过","则看那白杨村里人呜咽",127],["不如生前一击褫其魄","君不见荆轲匕首渐离筑",128],["尔树安得仍以不材终","君不见七星坛前七株桧",129],["画留石上永永成形模","君不见欧公当年石月屏",130],["将视齐州九点如稊糠","君不见金轮才出东溟底",131],["明年下视枯骨荒草缠","君不见阴平天险不可当",132],["急湍拍岸声声含呜咽","君不见山之绝顶鹰为窠",133],["可曾携汝起舞扬双眉","又不知雁门关外荷戈日",134],["叛臣不必定在节使府","坐令绛灌无文随陆不武",135],["果然龙蛇蟠我喉舌间","使我说天九难说地九难",136],["亦将听其嵯峨而潺湲","君不见仲尼没后圣道孤",137],["习见积薪颠倒成玉邱","君不见驽马立仗在御阶",138],["却无端催着桃花飘荡","者心情付春雨绕遍天壤",139],["奚取荆卿匕首渐离筑","君不见萧何下狱韩彭死",140],["到头来谁见把秋挨过","则看那白杨村里人呜咽",141],["可能朝宗东注觅海道","君不见耒阳禹力所不到",142],["相门出相那在金满籯","又不见燕山教子以义方",143]]});
